//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::hash::byte_array_hash`; the
//! native twin is `benches/native/Bench/ByteArrayHash.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::hash;
use lean_runtime_bench::{mixed, run, step, SEED};
use std::hint::black_box;
#[allow(unused_variables)]
fn kernel(inp: &Vec<u8>, n: u64) -> u64 {
    let b = inp;
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(hash::byte_array_hash(black_box(b.as_slice())));
    }
    acc as u64
}

fn main() {
    run(|| mixed().into_bytes(), kernel)
}
